#!/usr/bin/env node
"use strict";
const { execSync } = require("child_process");
const fs = require("fs");

const NAME = "jsonfmt";
const CAN_WRITE = true;
const args = process.argv.slice(2);
const write = args.includes("--write");
if (write && !CAN_WRITE) {
  console.error(NAME + ": unknown option --write");
  process.exit(2);
}

let files = args.filter((a) => !a.startsWith("--"));
if (args.includes("--changed")) {
  const base = execSync("git describe --tags --abbrev=0").toString().trim();
  files = execSync("git diff --name-only " + base + ' -- "*.json"').toString().split("\n").filter(Boolean);
}

const canonical = (text) => JSON.stringify(JSON.parse(text), null, 2) + "\n";
let bad = 0;
for (const file of files) {
  if (!fs.existsSync(file)) continue;
  const text = fs.readFileSync(file, "utf8");
  if (text === canonical(text)) continue;
  if (write) {
    fs.writeFileSync(file, canonical(text));
    console.log(NAME + ": fixed " + file);
  } else {
    console.error(file + ": formatting differs from the expected style");
    bad++;
  }
}
if (bad > 0) {
  console.error(NAME + ": " + bad + " file(s) with errors");
  process.exit(1);
}
console.log(NAME + ": ok");
